1	const RELATIVE = /^(\d+)([smhd])$/;
2	const UNIT_MS = { s: 1000, m: 60_000, h: 3_600_000, d: 86_400_000 };
3	
4	/** A `--since` value: ISO 8601, or relative to now (`2h`, `30m`). Returns null when it can't be read. */
5	export function parseWhen(value, now = Date.now()) {
6	  const rel = RELATIVE.exec(value);
7	  if (rel) return new Date(now - Number(rel[1]) * UNIT_MS[rel[2]]);
8	  const t = Date.parse(value);
9	  return Number.isNaN(t) ? null : new Date(t);
10	}
