6	function parseArgs(argv) {
7	  const opts = { grep: null, since: null, format: "text", file: null };
8	  for (let i = 0; i < argv.length; i++) {
9	    const a = argv[i];
10	    if (a === "--grep") opts.grep = argv[++i];
11	    else if (a === "--since") opts.since = argv[++i];
12	    else if (a === "--format") opts.format = argv[++i];
13	    else opts.file = a;
14	  }
15	  return opts;
16	}
