18	export async function main(argv) {
19	  const opts = parseArgs(argv);
20	  if (!opts.file) {
21	    console.error("usage: logslice [--grep <regex>] [--since <time>] [--format text|json] <file>");
22	    process.exit(1);
23	  }
24	  const re = opts.grep ? new RegExp(opts.grep) : null;
25	  const since = opts.since ? parseWhen(opts.since) : null;
26	  const rl = readline.createInterface({ input: fs.createReadStream(opts.file), crlfDelay: Infinity });
27	  let matched = 0;
28	  for await (const line of rl) {
29	    if (re && !re.test(line)) continue;
30	    if (since) {
31	      const at = parseStamp(line);
32	      if (at && at < since) continue;
33	    }
34	    matched++;
35	    process.stdout.write(formatLine(line, opts.format) + "\n");
36	  }
37	  return matched > 0 ? 0 : 1;
38	}
