3	export interface HttpOptions {
4	  timeoutMs?: number;
5	  retries?: number;
6	  headers?: Record<string, string>;
7	}
8	
9	async function request<T>(method: string, url: string, body: unknown, opts: HttpOptions): Promise<T> {
10	  const retries = opts.retries ?? 2;
11	  for (let attempt = 0; ; attempt++) {
12	    const started = Date.now();
13	    try {
14	      const res = await fetch(url, {
15	        method,
16	        headers: { "content-type": "application/json", ...opts.headers },
17	        body: body === undefined ? undefined : JSON.stringify(body),
18	        signal: AbortSignal.timeout(opts.timeoutMs ?? 5000),
19	      });
20	      log.debug({ method, url, status: res.status, ms: Date.now() - started }, "http");
21	      if (res.status >= 500 && attempt < retries) continue;
22	      if (!res.ok) throw new Error(`${method} ${url} → ${res.status}`);
23	      return (await res.json()) as T;
24	    } catch (err) {
25	      if (attempt >= retries) throw err;
26	      log.warn({ method, url, attempt, err: String(err) }, "http retry");
27	    }
28	  }
29	}
30	
31	export function httpGet<T>(url: string, opts: HttpOptions = {}): Promise<T> {
32	  return request<T>("GET", url, undefined, opts);
33	}
34	
35	export function httpPost<T>(url: string, body: unknown, opts: HttpOptions = {}): Promise<T> {
36	  return request<T>("POST", url, body, opts);
37	}
